            if not seen[i][j]:
                v=g[i][j]; q=[(i,j)]; seen[i][j]=True; c=set()
                while q:
                    x,y=q.pop(); c.add((x,y))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
